/** Project-only unit context, carried by the existing message field and endpoint. */
export function withSelectedUnit(message, unit) {
  const text=String(message || '');
  const value=String(unit??'').trim();
  if(!/^[A-Za-z0-9][A-Za-z0-9 -]{0,15}$/.test(value))return text;
  return `Unidad de interés: ${value}. Indicada por el visitante; existencia y disponibilidad por confirmar.\n${text}`;
}

export function initializePlaza(root) {
  const form=root.querySelector('form[data-project-request]');
  if(!form)return;
  let selected='';
  const panel=root.querySelector('#plc-unit-context'),label=root.querySelector('#plc-unit-selected');
  const interest=root.querySelector('#plc-unit-interest');
  const message=form.elements.mensaje;
  const select=unit=>{
    const value=String(unit??'').trim();
    selected=/^[A-Za-z0-9][A-Za-z0-9 -]{0,15}$/.test(value)?value:'';
    if(panel)panel.hidden=!selected;
    if(label)label.textContent=selected?`Unidad de interés: ${selected}. Se confirmará al cotizar.`:'';
    message.maxLength=1600-withSelectedUnit('',selected).length;
  };
  root.addEventListener('click',event=>{
    const unit=event.target.closest('[data-plaza-unit]');
    if(unit && !form.querySelector('fieldset').disabled && !form.hasAttribute('aria-busy'))select(unit.dataset.plazaUnit);
  });
  root.querySelector('#plc-unit-clear')?.addEventListener('click',()=>{
    if(!form.hasAttribute('aria-busy')){select('');if(interest)interest.value='';}
  });
  interest?.addEventListener('input',()=>{
    if(!form.hasAttribute('aria-busy')&&!form.querySelector('fieldset').disabled){
      const valid=!interest.value.trim()||/^[A-Za-z0-9][A-Za-z0-9 -]{0,15}$/.test(interest.value.trim());
      interest.setCustomValidity(valid?'':'Usa hasta 16 letras, números, espacios o guiones.');
      select(interest.value);
    }
  });
  // FormData is constructed by the existing request module. No second submit handler.
  form.addEventListener('formdata',event=>{
    event.formData.set('mensaje',withSelectedUnit(event.formData.get('mensaje'),selected));
  });
  form.addEventListener('reset',()=>select(''));
  const filter=root.querySelector('#plc-plan-filter'),plans=[...root.querySelectorAll('[data-plan-type]')];
  if(!filter)return;
  filter.closest('.plc-plan-controls').hidden=false;
  filter.addEventListener('change',()=>{
    let count=0;
    for(const plan of plans){plan.hidden=!!filter.value&&plan.dataset.planType!==filter.value;if(!plan.hidden)count++;}
    root.querySelector('#plc-plan-count').textContent=`${count} plano${count===1?'':'s'}`;
  });
}
if(typeof document!=='undefined'){
  const root=document.querySelector('.plaza-detail');
  if(root)initializePlaza(root);
}

import {validateCommercialFields, normalizedCommercialFields, focusCommercialField} from './commercial-fields.mjs';
import { createFormOperation } from './form-operation.mjs';
import { resolveProjectIdentity } from './project-identity.mjs';
import { bindRutField } from './rut-field.mjs?v=20261026-required-1';
import { priceFromLabel } from './catalog-model.mjs?v=20261029-crescer-1';

/** Use the existing advisory contract; no new destination or provider fields. */
export function composeProjectRequest({values,project,intent,startedAt}) {
  if (!project?.bodyProjectSlug || !/^\/[a-z0-9-]+\.html(?:#etapa-\d+)?$/.test(project.detalleUrl || '')) throw Error('No pudimos identificar el proyecto. Abre la solicitud desde su ficha.');
  if (!['cotizacion','llamada'].includes(intent)) throw Error('Selecciona el tipo de solicitud.');
  const invalid=validateCommercialFields(values);if(Object.keys(invalid).length)throw Error('Revisa los datos de identificación y contacto.');
  const message = String(values.mensaje || '').trim(), time = String(values.franja || '').trim();
  if (message.length > 1600 || time.length > 100) throw Error('Reduce el mensaje o la preferencia horaria antes de enviar.');
  const lines = ['Solicitud: '+(intent === 'llamada' ? 'Quiero que me llamen' : 'Solicitar cotización'),
    'Ficha de origen: https://sollahms.cl'+project.detalleUrl];
  if(project.nombre)lines.push('Proyecto: '+project.nombre);
  if(project.inmobiliaria)lines.push('Inmobiliaria: '+project.inmobiliaria);
  if(Object.hasOwn(project,'precioDesdeUF'))lines.push('Referencia del proyecto: '+priceFromLabel(project.precioDesdeUF,project.precioDecimales)+'. No es el precio definitivo de una unidad.');
  if (intent === 'llamada' && time) lines.push('Horario preferido (no es una reserva): '+time);
  if (message) lines.push('Mensaje del visitante: '+message);
  const mensaje=lines.join('\n');
  if (mensaje.length>2000) throw Error('Reduce el mensaje antes de enviar.');
  return {...normalizedCommercialFields(values),solicitud:intent,
    objetivo:values.objetivo || '',mensaje,consent:values.consent===true,
    website:values.website || '',startedAt,proyecto:project.bodyProjectSlug};
}

export function validateProjectRequest(values,intent) {
  const errors=validateCommercialFields(values);
  if(!['cotizacion','llamada'].includes(intent))errors.solicitud='Selecciona el tipo de solicitud.';
  if (String(values.mensaje||'').length>1600)errors.mensaje='Usa hasta 1.600 caracteres en tu mensaje.';
  if (values.consent!==true)errors.consent='Autoriza el uso de tus datos para responder la solicitud.';
  return errors;
}

if (typeof document!=='undefined') {
  const form=document.querySelector('form[data-project-request]');
  if(form) initializeProjectRequest(form);
}

function initializeProjectRequest(form) {
  const panel=form.closest('[data-project-slug]'),fields=document.getElementById('advisory-fields'),status=document.getElementById('advisory-status');
  const main=form.closest('main'),header=document.querySelector('body>header');
  const headerSize=()=>{if(header)main.style.setProperty('--pj-header-height',header.getBoundingClientRect().height+'px');};
  headerSize();if(header&&'ResizeObserver' in window)new ResizeObserver(headerSize).observe(header);
  const submit=form.querySelector('button[type=submit]'),modes=panel.querySelectorAll('[data-request-mode]');
  const ids={nombre:'name',rut:'rut',correo:'email',telefono:'phone',mensaje:'message',consent:'consent'};
  const inputs=Object.fromEntries(Object.keys(ids).map(n=>[n,form.elements[n]]));
  const rutField=bindRutField(inputs.rut,document.getElementById('advisory-rut-error'));
  const startedAt=Date.now(),operation=createFormOperation({name:'project-request:'+panel.dataset.projectSlug});
  let intent='cotizacion',sending=false,completed=false,project=null,catalogue=null;
  let stage=/^#etapa-([1-9]\d?)$/.exec(location.hash)?.[1] ?? null;
  const show=(message,state='error')=>{status.textContent=message;status.dataset.state=state;};
  const error=(name,message)=>{const e=document.getElementById('advisory-'+ids[name]+'-error');if(!e||!inputs[name])return;e.textContent=message;e.hidden=!message;inputs[name].setAttribute('aria-invalid',String(!!message));};
  const values=()=>({...Object.fromEntries(new FormData(form)),consent:inputs.consent.checked});
  const setMode=mode=>{
    if(sending||completed)return;
    intent=mode;
    document.getElementById('advisory-time-field').hidden=mode!=='llamada';form.elements.franja.disabled=mode!=='llamada';
    document.getElementById('advisory-form-title').textContent=mode==='llamada'?'Quiero que me llamen':'Solicitar cotización';
    panel.querySelector('.advisory-form-intro').textContent=mode==='llamada'?'Completa tus datos de identificación y contacto para coordinar una conversación sobre este proyecto. El horario es una preferencia, no una cita confirmada.':'Completa tus datos de identificación y contacto. Confirmaremos la información necesaria para preparar una respuesta sobre este proyecto.';
    submit.textContent=mode==='llamada'?'Solicitar llamada':'Solicitar cotización';
    modes.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.requestMode===mode)));

  };
  const resolve=()=>{
    project=resolveProjectIdentity(catalogue,panel.dataset.projectSlug,stage);
    if(!project)throw Error('No pudimos identificar el proyecto. Conserva tus datos y vuelve a abrir la solicitud desde su ficha.');
    document.getElementById('advisory-project-context').textContent='Tu solicitud sobre '+project.nombre;
  };
  const contextReady=(async()=>{
    const response=await fetch('/data/proyectos.json',{signal:AbortSignal.timeout(10000)});
    if(!response.ok)throw Error('No pudimos cargar el proyecto. Conserva tus datos e intenta nuevamente desde su ficha.');
    catalogue=await response.json();resolve();
  })();
  // Handle rejection now as well as at submit, avoiding an unhandled promise.
  contextReady.catch(()=>{});
  for(const [name,input] of Object.entries(inputs))input.addEventListener('input',()=>error(name,''));
  modes.forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.requestMode)));
  document.addEventListener('click',event=>{
    const a=event.target.closest('a[data-request-intent]');if(!a)return;
    setMode(a.dataset.requestIntent);
    if(!completed&&!sending)inputs.nombre.focus({preventScroll:true});
  });
  window.addEventListener('hashchange',()=>{
    const requested=/^#etapa-([1-9]\d?)$/.exec(location.hash)?.[1];
    if(requested&&!sending&&!completed){stage=requested;if(catalogue)try{resolve();}catch(e){show(e.message);}}
  });
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(sending||completed)return;
    Object.keys(inputs).forEach(n=>error(n,''));
    rutField.validate();
    const entered=values(),invalid=validateProjectRequest(entered,intent);
    if(Object.keys(invalid).length){
      for(const [name,message] of Object.entries(invalid))error(name,message);
      show('Revisa los campos indicados. Aún no se ha enviado tu solicitud.');
      focusCommercialField(inputs[Object.keys(invalid)[0]]);return;
    }
    sending=true;submit.disabled=true;submit.textContent='Enviando…';modes.forEach(b=>b.disabled=true);form.setAttribute('aria-busy','true');show('Estamos enviando tu solicitud.','sending');
    try{
      await contextReady;resolve();
      const payload=composeProjectRequest({values:entered,project,intent,startedAt});
      const attempt=await operation.prepare(payload);fields.disabled=true;
      const response=await fetch('/api/advisory',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':attempt.key},body:attempt.body,signal:AbortSignal.timeout(15000)});
      const result=await response.json();
      if(!response.ok){
        if(!attempt.reused&&([400,403,413,415].includes(response.status)||['preview_read_only','contact_configuration_unavailable'].includes(result.code)))operation.discard();
        for(const [name,message] of Object.entries(result.fieldErrors||{}))error(name,message);
        throw Error(result.error||'No pudimos confirmar el envío. Reintenta sin cambiar los datos.');
      }
      if(result.ok!==true||result.providerAccepted!==true||result.deliveryConfirmed!==false)throw Error('No pudimos confirmar el envío. Reintenta sin cambiar los datos o escribe a contacto@sollahms.cl.');
      completed=true;operation.complete();form.reset();show('Solicitud '+(intent==='llamada'?'de llamada':'de cotización')+' aceptada para envío a Sollahms. Este aviso no confirma entrega al buzón, disponibilidad ni una cita. Usaremos tus datos de contacto para coordinar el siguiente paso.','success');status.focus();
    }catch(e){
      operation.uncertain();show(['TypeError','TimeoutError','SyntaxError'].includes(e.name)?'No pudimos confirmar el envío. Tus datos siguen aquí. Reintenta sin cambiarlos o escribe a contacto@sollahms.cl.':e.message);status.focus();
    }finally{
      sending=false;form.removeAttribute('aria-busy');fields.disabled=completed;submit.disabled=completed;modes.forEach(b=>b.disabled=completed);
      submit.textContent=completed?'Solicitud aceptada':intent==='llamada'?'Solicitar llamada':'Solicitar cotización';
    }
  });
  fields.disabled=false;document.getElementById('advisory-unavailable').hidden=true;
}

import {priceFromLabel,validPrice,projectOffer as selectedOffer,projectFacts,filterAndSort,VIEW_KEY} from './catalog-model.mjs?v=20261029-crescer-1';
import {createFilterControls} from './catalog-filter-controls.mjs?v=20261029-crescer-1';
import {defaults,matchedLabels} from './catalog-filter-engine.mjs?v=20261029-filters-1';
const $=id=>document.getElementById(id);
const controls={assetType:$('asset-type'),sortOrder:$('sort-order')};
const grid=$('project-grid'),count=$('project-count'),message=$('catalog-message');
const viewButtons=[...document.querySelectorAll('[data-catalog-view]')];
let projects=[],capacitySearch=null,view='cards',mapInstance=null,mapPromise=null,mapResults=[],filterControls=null;
const mapHost=$('catalog-map');
const element=(tag,text,classes)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(classes)e.className=classes;return e;};
const values=()=>filterControls?.values()??defaults();
const remember=()=>filterControls?.remember();
function ensureMap(){
  if(mapInstance){mapInstance.show();mapInstance.update(mapResults,{assetType:controls.assetType.value,filters:values()});return;}
  if(mapPromise)return;
  mapHost.setAttribute('aria-busy','true');mapHost.replaceChildren(element('p','Cargando mapa…','catalog-map-status'));
  mapPromise=import('./catalog-map.mjs?v=20261029-crescer-1').then(({createCatalogMap})=>createCatalogMap({host:mapHost})).then(instance=>{
    mapInstance=instance;if(view==='map'){instance.show();instance.update(mapResults,{assetType:controls.assetType.value,filters:values()});}else instance.hide();
  }).catch(error=>{
    mapHost.setAttribute('aria-busy','false');const note=element('p','El mapa no pudo cargar. Puedes seguir explorando todos los resultados en Tarjetas o Listado.');note.setAttribute('role','status');
    const fallback=element('button','Continuar en Listado','catalog-text-button');fallback.type='button';fallback.addEventListener('click',()=>viewButtons.find(b=>b.dataset.catalogView==='list').click());mapHost.replaceChildren(note,fallback);
  });
}
function applyView(){
  grid.dataset.view=view;grid.hidden=view==='map';mapHost.hidden=view!=='map';
  viewButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.catalogView===view)));
  if(view==='map'){grid.replaceChildren();ensureMap();}else mapInstance?.hide();
}
viewButtons.forEach(button=>button.addEventListener('click',()=>{
  if(button.dataset.catalogView===view)return;
  view=button.dataset.catalogView;applyView();render();remember();
  try{localStorage.setItem(VIEW_KEY,view);}catch{}
  // The same DOM items changed geometry. Refresh the unchanged shared scroll helper.
  window.dispatchEvent(new Event('resize'));
}));
function card(project){
  const article=element('article',undefined,'catalog-item');article.dataset.project=project.slug;
  const group=element('div',undefined,'catalog-card');
  const cover=element('div',undefined,'catalog-cover s-parallax-frame');
  const placeholder=()=>{const box=element('div',undefined,'catalog-cover-placeholder');const brand=element('img');brand.src='/assets/branding/sollahms-logo-light.svg';brand.alt='Sollahms';brand.width=114;brand.height=22;box.append(brand,element('span','Imagen no disponible'));cover.replaceChildren(box);};
  if(typeof project.imagenPrincipal==='string'&&/^\/assets\/propiedades\/[a-z0-9/._-]+\.(?:webp|jpe?g|png)$/i.test(project.imagenPrincipal)){
    const img=element('img',undefined,'catalog-cover-image');img.src=project.imagenPrincipal;img.alt=project.imagenAlt||'Imagen del proyecto '+project.nombre;img.width=1600;img.height=900;img.loading='lazy';img.decoding='async';img.addEventListener('error',placeholder,{once:true});cover.append(img);
  }else placeholder();
  const summary=element('div',undefined,'catalog-summary');
  const identity=element('div',undefined,'catalog-identity');const title=element('h2',project.nombre,'catalog-card-title');title.id='catalog-'+project.slug;article.setAttribute('aria-labelledby',title.id);
  identity.append(title,element('p',[project.comuna,project.region].filter(Boolean).join(' · '),'catalog-location'));
  if(project.inmobiliaria)identity.append(element('p',project.inmobiliaria,'catalog-builder'));
  summary.append(identity);
  const facts=projectFacts(project,controls.assetType.value);
  if(facts.length){const dl=element('dl',undefined,'catalog-facts');for(const fact of facts){const row=element('div');row.append(element('dt',fact.label),element('dd',fact.value));dl.append(row);}summary.append(dl);}
  const matches=matchedLabels(project,values());
  if(matches.length){const badges=element('ul',undefined,'cf-match-list');badges.setAttribute('aria-label','Coincidencias verificadas');for(const label of matches.slice(0,3))badges.append(element('li',label));if(matches.length>3)badges.append(element('li','+'+(matches.length-3)+' coincidencias'));summary.append(badges);}
  group.append(cover,summary);article.append(group);
  // Action area is deliberately outside the opacity group; finance controls stay static too.
  const body=element('div',undefined,'catalog-card-body');body.dataset.scrollStatic='';
  const actions=element('div',undefined,'catalog-actions'),price=element('div',undefined,'catalog-price');const offer=selectedOffer(project);
  if(validPrice(offer.value)){
    price.append(element('p',priceFromLabel(offer.value,project.precioDecimales),'catalog-price-value'));
    if(offer.typology)price.append(element('p',offer.typology==='Local'?'Local comercial':offer.typology,'catalog-price-type'));
  }else price.append(element('p',priceFromLabel(null),'catalog-price-unavailable'));
  actions.append(price);
  if(typeof project.detalleUrl==='string'&&/^\/[a-z0-9-]+\.html$/.test(project.detalleUrl)){
    const link=element('a','Ver detalles','catalog-details-link');link.href=project.detalleUrl;link.setAttribute('aria-label','Ver detalles de '+project.nombre);actions.append(link);
  }
  body.append(actions);article.append(body);
  if(!(project.preciosPorTipologia&&controls.assetType.value==='Comercial'))capacitySearch?.decorateCard(article,project);
  const financial=body.querySelector('.capacity-result');
  if(financial){
    // Review dates remain in the source data; the financial scenario keeps all amounts/conditions.
    financial.querySelectorAll('dt').forEach(dt=>{if(dt.textContent==='Revisión del precio')dt.parentElement.remove();});
    const details=element('details',undefined,'catalog-finance');details.dataset.scrollStatic='';
    details.append(element('summary','Ver escenario financiero'),financial);article.append(details);
  }
  return article;
}
function render(){
  const sorted=filterAndSort(projects,values());
  if(controls.sortOrder.value==='original')capacitySearch?.sortProjects(sorted);
  mapResults=sorted;
  if(view==='map'){grid.replaceChildren();if(mapInstance)mapInstance.update(sorted,{assetType:controls.assetType.value,filters:values()});else ensureMap();}
  else grid.replaceChildren(...sorted.map(card));
  count.textContent=sorted.length===projects.length?projects.length+' proyectos':sorted.length+' de '+projects.length+' proyectos';
  message.textContent=filterControls?.issue()||(sorted.length?'':'No encontramos coincidencias documentadas con esta combinación. Puedes quitar una característica, ampliar el rango o modificar la ubicación.');
  $('catalog-feedback').hidden=!!sorted.length;$('empty-reset').hidden=!!sorted.length;
  filterControls?.updateCount(sorted.length);remember();
}
async function load(){
  try{
    const response=await fetch('/data/proyectos.json',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('catalogue unavailable');
    const data=await response.json();if(!Array.isArray(data)||new Set(data.map(p=>p.slug)).size!==data.length)throw Error('catalogue identity');
    data.forEach(project=>{if(!project||typeof project.slug!=='string'||typeof project.nombre!=='string'||!/^\/[a-z0-9-]+\.html$/.test(project.detalleUrl))throw Error('catalogue identity');});
    let index={projects:{},filters:[],typologies:[]};
    try{const response=await fetch('/data/catalog-facets.json?v=20261029-filters-1',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('facets unavailable');index=await response.json();if(index.schemaVersion!==1||!index.projects)throw Error('facets schema');}
    catch{const note=$('advanced-data-status');note.hidden=false;note.textContent='Los filtros por características no pudieron cargar. Puedes seguir buscando por ubicación, nombre y precio.';}
    projects=data.map(p=>({...p,_facets:index.projects[p.slug]??{assetTypes:p.tiposActivos??[p.tipoActivo].filter(Boolean),states:[p.estado].filter(Boolean)}}));
    filterControls=createFilterControls({projects,index,onChange:render,getView:()=>view,setView:next=>{view=next;applyView();}});applyView();render();
    $('catalog-static-directory').hidden=true;
    viewButtons.forEach(c=>c.disabled=false);
    import('/assets/js/purchase-capacity-ui.mjs').then(({initializeCapacitySearch})=>{capacitySearch=initializeCapacitySearch({projects,onChange:render});$('capacity-toggle').disabled=false;}).catch(()=>{$('capacity-summary').textContent='El buscador financiero no pudo cargar. Puedes seguir utilizando los filtros del catálogo.';});
  }catch(error){
    grid.replaceChildren();count.textContent='';$('catalog-feedback').hidden=false;$('empty-reset').hidden=true;
    message.textContent=['TimeoutError','AbortError'].includes(error.name)?'La carga tardó demasiado. Puedes explorar las fichas en el directorio siguiente.':'No pudimos cargar el catálogo. Puedes explorar las fichas en el directorio siguiente.';
  }finally{grid.setAttribute('aria-busy','false');}
}
load();

import {advancedFilterAndSort} from './catalog-filter-engine.mjs?v=20261029-filters-1';
// Public catalogue facts only. This module never changes source records.
export const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('es-CL');
export const validPrice = value => typeof value === 'number' && Number.isFinite(value) && value > 0;
export const priceFromLabel = (value,decimals=0) => validPrice(value) ? 'Desde UF '+value.toLocaleString('es-CL',{minimumFractionDigits:decimals===2?2:0,maximumFractionDigits:2}) : 'Desde: consultar precio';
export const stages = project => project.inmobiliaria === 'Ecasa' && Array.isArray(project.etapasComerciales) && project.etapasComerciales.length > 1
  ? project.etapasComerciales : Array.isArray(project.etapas) ? project.etapas : [];
export const commercialReference = project => project.inmobiliaria === 'Ecasa' && stages(project).length > 1
  ? stages(project).find(stage => stage.slug === project.etapaReferenciaSlug) : null;
export const projectStates = project => [project.estado, ...stages(project).map(stage => stage.estado)].filter(value => typeof value === 'string' && value.length);
export function assetTypes(project) {
  const explicit=[...(project.tiposActivos??[]),project.tipoActivo].filter(Boolean);
  if(explicit.length)return [...new Set(explicit)];
  // Existing residential typologies establish use, without inventing house/apartment characteristics.
  const typologies=project.tipologias??[];
  const residential=typologies.some(value=>/^(?:Estudio|\d+ dormitorios?)$/i.test(value));
  const commercial=typologies.includes('Local');
  return [...(residential?['Residencial']:[]),...(commercial?['Comercial']:[]),...(residential&&commercial?['Mixto']:[])];
}
export function selectedOffer(project, selectedType='') {
  if(!Array.isArray(project.preciosPorTipologia))return {value:validPrice(project.precioDesdeUF)?project.precioDesdeUF:null,typology:project.precioDesdeTipologia??null};
  const offers=project.preciosPorTipologia.filter(row=>validPrice(row.precioDesdeUF)&&(selectedType==='Comercial'?row.tipologia==='Local':selectedType==='Residencial'?row.tipologia!=='Local':true));
  const lowest=offers.reduce((best,row)=>!best||row.precioDesdeUF<best.precioDesdeUF?row:best,null);
  return {value:lowest?.precioDesdeUF??null,typology:lowest?.tipologia??null};
}
export const projectOffer=project=>({value:validPrice(project.precioDesdeUF)?project.precioDesdeUF:null,typology:project.precioDesdeTipologia??null});
export const searchableValues = project => [...['nombre','inmobiliaria','comuna','region','direccion','slug'].map(key=>project[key]),...stages(project).map(stage=>stage.nombre)];
export function filterAndSort(projects, filters={}) {
  if(filters.version===2)return advancedFilterAndSort(projects,filters);
  const query=normalize((filters.search??'').trim());
  const max=filters.maxPriceInput===''||filters.maxPriceInput==null?null:Number(filters.maxPriceInput);
  const hasMax=max!==null&&Number.isFinite(max)&&max>=0;
  const rows=projects.filter(project=>(!filters.assetType||assetTypes(project).includes(filters.assetType))
    &&(!filters.region||project.region===filters.region)&&(!filters.commune||project.comuna===filters.commune)
    &&(!filters.state||projectStates(project).some(s=>normalize(s)===normalize(filters.state)))
    &&(!hasMax||(validPrice(selectedOffer(project,filters.assetType).value)&&selectedOffer(project,filters.assetType).value<=max))
